-- Filename generated by Supabase CLI 2.121.0 in Actions run 38594761469.
-- Additive foundation: existing events are not moved or unpublished.
begin;
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
grant usage on schema private to authenticated;

create table private.platform_owner (
  singleton boolean primary key default true check (singleton),
  user_id uuid not null unique references auth.users(id) on delete restrict,
  created_at timestamptz not null default now()
);
alter table private.platform_owner enable row level security;
revoke all on private.platform_owner from public, anon, authenticated;
create table public.organizations (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{2,63}$'),
  name text not null check (char_length(btrim(name)) between 1 and 160),
  status text not null default 'active' check (status in ('active','suspended')),
  event_limit integer check (event_limit between 1 and 10000),
  version integer not null default 0,
  created_at timestamptz not null default now(),
  unique (id,slug)
);
create table public.organization_memberships (
  organization_id uuid not null references public.organizations(id) on delete restrict,
  user_id uuid not null references auth.users(id) on delete restrict,
  role text not null check (role in ('owner','admin')),
  status text not null default 'active' check (status in ('active','disabled')),
  version integer not null default 0,
  created_at timestamptz not null default now(),
  primary key (organization_id,user_id)
);
create index organization_memberships_user_idx on public.organization_memberships(user_id,organization_id);
create table public.organization_invitations (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete restrict,
  email text not null check (email=lower(btrim(email)) and char_length(email)<=254 and email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'),
  role text not null check (role in ('owner','admin')),
  expires_at timestamptz not null default (now()+interval '7 days'),
  accepted_by uuid references auth.users(id) on delete restrict,
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);
create index organization_invitations_recipient_idx on public.organization_invitations(email,expires_at);
create unique index organization_invitations_pending_idx on public.organization_invitations(organization_id,email)
  where accepted_by is null and revoked_at is null;

-- Public routing needs only the organization's slug. The composite FK prevents
-- contradictory ownership without exposing private organization records.
alter table public.events
  add column organization_id uuid,
  add column organization_slug text,
  add column platform_version integer not null default 0,
  add column brand_logo_url text not null default '' check (brand_logo_url='' or (brand_logo_url ~ '^https://' and char_length(brand_logo_url)<=2048)),
  add constraint events_organization_pair check ((organization_id is null)=(organization_slug is null)),
  add constraint events_organization_fk foreign key (organization_id,organization_slug) references public.organizations(id,slug) on delete restrict;
create index events_organization_idx on public.events(organization_id,created_at);
create table private.platform_creation_requests (
  request_id uuid primary key,
  actor_id uuid not null references auth.users(id) on delete restrict,
  kind text not null check (kind in ('organization','event')),
  payload jsonb not null,
  organization_id uuid not null references public.organizations(id) on delete restrict,
  event_id uuid references public.events(id) on delete restrict,
  created_at timestamptz not null default now()
);
alter table private.platform_creation_requests enable row level security;
revoke all on private.platform_creation_requests from public, anon, authenticated;
create table public.platform_audit_log (
  id bigint generated always as identity primary key,
  actor_id uuid not null references auth.users(id) on delete restrict,
  organization_id uuid not null references public.organizations(id) on delete restrict,
  event_id uuid references public.events(id) on delete restrict,
  action text not null,
  details jsonb not null default '{}',
  created_at timestamptz not null default now()
);
create index platform_audit_organization_idx on public.platform_audit_log(organization_id,created_at desc);

create function private.platform_verified_email() returns text language sql stable security definer set search_path='' as $$
  select lower(btrim(email)) from auth.users where id=auth.uid() and email_confirmed_at is not null;
$$;
create function private.is_platform_owner() returns boolean language sql stable security definer set search_path='' as $$
  select auth.uid() is not null and private.platform_verified_email() is not null
    and exists(select 1 from private.platform_owner where user_id=auth.uid());
$$;
create function private.can_manage_organization(p_organization uuid) returns boolean language sql stable security definer set search_path='' as $$
  select auth.uid() is not null and private.platform_verified_email() is not null and exists(
    select 1 from public.organizations o where o.id=p_organization and (private.is_platform_owner() or (o.status='active' and exists(
      select 1 from public.organization_memberships m where m.organization_id=o.id and m.user_id=auth.uid() and m.status='active' and m.role in ('owner','admin')))));
$$;
create function private.owns_organization(p_organization uuid) returns boolean language sql stable security definer set search_path='' as $$
  select auth.uid() is not null and private.platform_verified_email() is not null and exists(
    select 1 from public.organizations o where o.id=p_organization and (private.is_platform_owner() or (o.status='active' and exists(
      select 1 from public.organization_memberships m where m.organization_id=o.id and m.user_id=auth.uid() and m.status='active' and m.role='owner'))));
$$;
create function private.can_see_organization(p_organization uuid) returns boolean language sql stable security definer set search_path='' as $$
  select auth.uid() is not null and private.platform_verified_email() is not null and (private.is_platform_owner()
    or exists(select 1 from public.organization_memberships where organization_id=p_organization and user_id=auth.uid() and status='active')
    or exists(select 1 from public.organization_invitations where organization_id=p_organization and email=private.platform_verified_email()
      and revoked_at is null and accepted_by is null and expires_at>now()));
$$;
alter table public.organizations enable row level security;
alter table public.organization_memberships enable row level security;
alter table public.organization_invitations enable row level security;
alter table public.platform_audit_log enable row level security;
revoke all on public.organizations, public.organization_memberships, public.organization_invitations, public.platform_audit_log from public, anon, authenticated;
grant select on public.organizations, public.organization_memberships, public.organization_invitations, public.platform_audit_log to authenticated;
create policy organizations_read on public.organizations for select to authenticated using (private.can_see_organization(id));
create policy organization_memberships_read on public.organization_memberships for select to authenticated using (user_id=auth.uid() or private.owns_organization(organization_id));
create policy organization_invitations_read on public.organization_invitations for select to authenticated using (email=private.platform_verified_email() or private.owns_organization(organization_id));
create policy platform_audit_read on public.platform_audit_log for select to authenticated using (private.owns_organization(organization_id));

-- Staff management does not create attendee registration or participation consent.
-- Preserve the legacy role and disabled-registration semantics.
create or replace function public.is_event_admin(p_event uuid) returns boolean language sql stable security definer set search_path='' as $$
  select exists(select 1 from public.events e where e.id=p_event and (
    (e.organization_id is not null and private.can_manage_organization(e.organization_id))
    or ((e.organization_id is null or exists(select 1 from public.organizations o where o.id=e.organization_id and o.status='active')) and (
      exists(select 1 from public.attendees a where a.event_id=p_event and a.user_id=auth.uid() and a.status='approved' and a.access_role='admin')
      or exists(select 1 from public.event_admins a where a.event_id=p_event and a.user_id=auth.uid()
        and not exists(select 1 from public.attendees r where r.event_id=a.event_id and r.user_id=a.user_id and r.status<>'approved'))))));
$$;
-- Invoker trigger: direct Data API writes cannot attach/move a tenant or bypass
-- the versioned event/publishing functions. Legacy event writes are unchanged.
create function private.guard_platform_event_write() returns trigger language plpgsql set search_path='' as $$
begin
  if current_user in ('anon','authenticated') then
    if (tg_op<>'INSERT' and old.organization_id is not null) or (tg_op<>'DELETE' and new.organization_id is not null) then
      raise exception 'Use the workspace event actions' using errcode='42501';
    end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $$;
create trigger platform_event_write before insert or update or delete on public.events for each row execute function private.guard_platform_event_write();
create function private.platform_log(p_organization uuid,p_event uuid,p_action text,p_details jsonb default '{}') returns void language sql set search_path='' as $$
  insert into public.platform_audit_log(actor_id,organization_id,event_id,action,details) values(auth.uid(),p_organization,p_event,p_action,p_details);
$$;

create function private.platform_create_organization(p_request uuid,p_name text,p_slug text,p_owner_email text,p_event_limit integer default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_org uuid; v_payload jsonb; v_receipt private.platform_creation_requests;
begin
  if not private.is_platform_owner() then raise exception 'Agency access required' using errcode='42501'; end if;
  if p_request is null or p_name is null or p_slug is null or p_owner_email is null then raise exception 'Complete the subaccount details' using errcode='22023'; end if;
  v_payload:=jsonb_build_object('name',btrim(p_name),'slug',p_slug,'owner_email',lower(btrim(p_owner_email)),'event_limit',p_event_limit);
  perform pg_advisory_xact_lock(hashtextextended('platform-create:'||p_request::text,0));
  select * into v_receipt from private.platform_creation_requests where request_id=p_request;
  if found then
    if v_receipt.actor_id<>auth.uid() or v_receipt.kind<>'organization' or v_receipt.payload<>v_payload then raise exception 'This request was already used for different details' using errcode='PT409'; end if;
    return v_receipt.organization_id;
  end if;
  insert into public.organizations(name,slug,event_limit) values(btrim(p_name),p_slug,p_event_limit) returning id into v_org;
  insert into public.organization_invitations(organization_id,email,role) values(v_org,lower(btrim(p_owner_email)),'owner');
  insert into private.platform_creation_requests(request_id,actor_id,kind,payload,organization_id) values(p_request,auth.uid(),'organization',v_payload,v_org);
  perform private.platform_log(v_org,null,'organization.created',jsonb_build_object('owner_invited',true));
  return v_org;
end $$;
create function private.platform_accept_invitation(p_invitation uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare v_invite public.organization_invitations; v_email text:=private.platform_verified_email(); v_org uuid;
begin
  if auth.uid() is null or v_email is null then raise exception 'Verify your email before accepting an invitation' using errcode='42501'; end if;
  select organization_id into v_org from public.organization_invitations where id=p_invitation and email=v_email;
  if v_org is null then raise exception 'This invitation is not available to your account' using errcode='42501'; end if;
  perform 1 from public.organizations where id=v_org and status='active' for update;
  if not found then raise exception 'This workspace is unavailable' using errcode='42501'; end if;
  select * into v_invite from public.organization_invitations where id=p_invitation for update;
  if v_invite.accepted_by=auth.uid() then return v_org; end if;
  if v_invite.accepted_by is not null or v_invite.revoked_at is not null or v_invite.expires_at<=now() then raise exception 'This invitation has expired or was revoked. Ask the owner for a new invitation.' using errcode='22023'; end if;
  insert into public.organization_memberships(organization_id,user_id,role) values(v_org,auth.uid(),v_invite.role)
    on conflict(organization_id,user_id) do update set role=case when organization_memberships.role='owner' and organization_memberships.status='active' then 'owner' else excluded.role end,
      status='active',version=organization_memberships.version+1;
  update public.organization_invitations set accepted_by=auth.uid() where id=p_invitation;
  perform private.platform_log(v_org,null,'invitation.accepted',jsonb_build_object('invitation_id',p_invitation));
  return v_org;
end $$;
create function private.platform_invite_member(p_organization uuid,p_email text,p_role text) returns uuid language plpgsql security definer set search_path='' as $$
declare v_invite uuid;
begin
  perform 1 from public.organizations where id=p_organization for update;
  if not private.owns_organization(p_organization) then raise exception 'Workspace owner access required' using errcode='42501'; end if;
  if p_role is null or p_role not in ('owner','admin') then raise exception 'Choose a valid workspace role' using errcode='22023'; end if;
  update public.organization_invitations set revoked_at=now() where organization_id=p_organization and email=lower(btrim(p_email)) and revoked_at is null and accepted_by is null;
  insert into public.organization_invitations(organization_id,email,role) values(p_organization,lower(btrim(p_email)),p_role) returning id into v_invite;
  perform private.platform_log(p_organization,null,'invitation.created',jsonb_build_object('invitation_id',v_invite,'role',p_role));
  return v_invite;
end $$;
create function private.platform_revoke_invitation(p_organization uuid,p_invitation uuid) returns void language plpgsql security definer set search_path='' as $$
begin
  perform 1 from public.organizations where id=p_organization for update;
  if not private.owns_organization(p_organization) then raise exception 'Workspace owner access required' using errcode='42501'; end if;
  update public.organization_invitations set revoked_at=coalesce(revoked_at,now()) where id=p_invitation and organization_id=p_organization and accepted_by is null;
  if not found then raise exception 'This pending invitation is no longer available' using errcode='PT409'; end if;
  perform private.platform_log(p_organization,null,'invitation.revoked',jsonb_build_object('invitation_id',p_invitation));
end $$;
create function private.platform_update_member(p_organization uuid,p_user uuid,p_role text,p_status text,p_version integer) returns void language plpgsql security definer set search_path='' as $$
declare v_member public.organization_memberships;
begin
  perform 1 from public.organizations where id=p_organization for update;
  if not private.owns_organization(p_organization) then raise exception 'Workspace owner access required' using errcode='42501'; end if;
  if p_role is null or p_role not in ('owner','admin') or p_status is null or p_status not in ('active','disabled') then raise exception 'Choose a valid role and status' using errcode='22023'; end if;
  select * into v_member from public.organization_memberships where organization_id=p_organization and user_id=p_user;
  if not found or p_version is distinct from v_member.version then raise exception 'Team access changed. Refresh before saving.' using errcode='PT409'; end if;
  if v_member.role='owner' and v_member.status='active' and (p_role<>'owner' or p_status<>'active') and
    (select count(*) from public.organization_memberships where organization_id=p_organization and role='owner' and status='active')<=1 then raise exception 'Keep at least one active workspace owner' using errcode='22023'; end if;
  update public.organization_memberships set role=p_role,status=p_status,version=version+1 where organization_id=p_organization and user_id=p_user;
  perform private.platform_log(p_organization,null,'membership.updated',jsonb_build_object('user_id',p_user,'role',p_role,'status',p_status));
end $$;
create function private.platform_update_organization(p_organization uuid,p_name text,p_version integer,p_status text default null,p_event_limit integer default null,p_set_limit boolean default false)
returns void language plpgsql security definer set search_path='' as $$
declare v_org public.organizations;
begin
  select * into v_org from public.organizations where id=p_organization for update;
  if not private.owns_organization(p_organization) then raise exception 'Workspace owner access required' using errcode='42501'; end if;
  if p_version is distinct from v_org.version then raise exception 'Workspace settings changed. Refresh before saving.' using errcode='PT409'; end if;
  if (p_status is not null or p_set_limit) and not private.is_platform_owner() then raise exception 'Agency access required' using errcode='42501'; end if;
  update public.organizations set name=btrim(p_name),status=coalesce(p_status,status),event_limit=case when p_set_limit then p_event_limit else event_limit end,version=version+1 where id=p_organization;
  perform private.platform_log(p_organization,null,'organization.updated');
end $$;

create function private.platform_validate_event(p_values jsonb,p_create boolean) returns void language plpgsql set search_path='' as $$
begin
  if p_values is null or jsonb_typeof(p_values)<>'object' then raise exception 'Supply event details' using errcode='22023'; end if;
  if exists(select 1 from jsonb_object_keys(p_values) k where k not in ('name','slug','tagline','timezone','start_date','end_date','brand_logo_url')) or (not p_create and p_values ? 'slug') then raise exception 'Unsupported event field' using errcode='22023'; end if;
  if nullif(btrim(p_values->>'name'),'') is null or char_length(p_values->>'name')>160 or not (p_values ? 'timezone') or not exists(select 1 from pg_catalog.pg_timezone_names where name=p_values->>'timezone') then raise exception 'Supply an event name and a valid timezone' using errcode='22023'; end if;
  if char_length(coalesce(p_values->>'tagline',''))>600 then raise exception 'Keep the description under 600 characters' using errcode='22023'; end if;
  if p_create and (p_values->>'slug' is null or (p_values->>'slug') !~ '^[a-z0-9][a-z0-9-]{2,100}$') then raise exception 'Choose a valid event URL' using errcode='22023'; end if;
end $$;
create function private.platform_create_event(p_organization uuid,p_request uuid,p_values jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare v_org public.organizations; v_event uuid; v_receipt private.platform_creation_requests; v_payload jsonb;
begin
  if not private.can_manage_organization(p_organization) then raise exception 'Workspace access required' using errcode='42501'; end if;
  if p_request is null then raise exception 'A creation request is required' using errcode='22023'; end if;
  perform private.platform_validate_event(p_values,true);
  v_payload:=jsonb_build_object('organization_id',p_organization,'values',p_values);
  perform pg_advisory_xact_lock(hashtextextended('platform-create:'||p_request::text,0));
  select * into v_receipt from private.platform_creation_requests where request_id=p_request;
  if found then
    if v_receipt.actor_id<>auth.uid() or v_receipt.kind<>'event' or v_receipt.payload<>v_payload then raise exception 'This request was already used for different details' using errcode='PT409'; end if;
    return v_receipt.event_id;
  end if;
  select * into v_org from public.organizations where id=p_organization for update;
  if not private.can_manage_organization(p_organization) then raise exception 'Workspace access required' using errcode='42501'; end if;
  if v_org.event_limit is not null and (select count(*) from public.events where organization_id=p_organization)>=v_org.event_limit then raise exception 'This workspace has reached its event limit. Contact the agency to add more events.' using errcode='22023'; end if;
  insert into public.events(organization_id,organization_slug,name,slug,tagline,timezone,start_date,end_date,brand_logo_url)
    values(p_organization,v_org.slug,btrim(p_values->>'name'),p_values->>'slug',coalesce(p_values->>'tagline',''),p_values->>'timezone',(p_values->>'start_date')::date,(p_values->>'end_date')::date,coalesce(p_values->>'brand_logo_url','')) returning id into v_event;
  insert into public.event_settings(event_id,welcome_title,welcome_body,sponsor_page_title,sponsor_page_description,directory_enabled,messaging_enabled,community_enabled,feed_enabled,self_service_access_enabled,announcements_enabled)
    values(v_event,p_values->>'name',coalesce(p_values->>'tagline',''),'Sponsors','Meet the organizations supporting this event.',false,false,false,false,false,false);
  insert into private.platform_creation_requests(request_id,actor_id,kind,payload,organization_id,event_id) values(p_request,auth.uid(),'event',v_payload,p_organization,v_event);
  perform private.platform_log(p_organization,v_event,'event.created');
  return v_event;
end $$;
create function private.platform_update_event(p_organization uuid,p_event uuid,p_version integer,p_values jsonb) returns void language plpgsql security definer set search_path='' as $$
declare v_event public.events;
begin
  perform 1 from public.organizations where id=p_organization for update;
  if not private.can_manage_organization(p_organization) then raise exception 'Workspace access required' using errcode='42501'; end if;
  select * into v_event from public.events where id=p_event and organization_id=p_organization for update;
  if not found then raise exception 'This event is not in your workspace' using errcode='42501'; end if;
  if p_version is distinct from v_event.platform_version then raise exception 'Event details changed. Refresh before saving.' using errcode='PT409'; end if;
  perform private.platform_validate_event(p_values,false);
  if v_event.published and ((p_values->>'start_date') is null or (p_values->>'end_date') is null) then raise exception 'Published events need start and end dates' using errcode='22023'; end if;
  update public.events set name=btrim(p_values->>'name'),tagline=coalesce(p_values->>'tagline',''),timezone=p_values->>'timezone',start_date=(p_values->>'start_date')::date,end_date=(p_values->>'end_date')::date,brand_logo_url=coalesce(p_values->>'brand_logo_url',''),platform_version=platform_version+1 where id=p_event;
  perform private.platform_log(p_organization,p_event,'event.details_updated');
end $$;
create function private.platform_publish_event(p_organization uuid,p_event uuid,p_version integer,p_published boolean) returns void language plpgsql security definer set search_path='' as $$
declare v_event public.events;
begin
  perform 1 from public.organizations where id=p_organization for update;
  if not private.can_manage_organization(p_organization) then raise exception 'Workspace access required' using errcode='42501'; end if;
  select * into v_event from public.events where id=p_event and organization_id=p_organization for update;
  if not found then raise exception 'This event is not in your workspace' using errcode='42501'; end if;
  if p_version is distinct from v_event.platform_version then raise exception 'Event details changed. Refresh before publishing.' using errcode='PT409'; end if;
  if p_published is null then raise exception 'Choose a publication state' using errcode='22023'; end if;
  if p_published and (v_event.start_date is null or v_event.end_date is null) then raise exception 'Add start and end dates before publishing' using errcode='22023'; end if;
  update public.events set published=p_published,platform_version=platform_version+1 where id=p_event;
  perform private.platform_log(p_organization,p_event,case when p_published then 'event.published' else 'event.unpublished' end);
end $$;
create function private.platform_legacy_events() returns table(id uuid,slug text,name text,published boolean) language plpgsql stable security definer set search_path='' as $$
begin
  if not private.is_platform_owner() then raise exception 'Agency access required' using errcode='42501'; end if;
  return query select e.id,e.slug,e.name,e.published from public.events e where e.organization_id is null order by e.created_at limit 200;
end $$;
create function private.platform_adopt_event(p_organization uuid,p_event uuid) returns void language plpgsql security definer set search_path='' as $$
declare v_org public.organizations; v_event public.events;
begin
  if not private.is_platform_owner() then raise exception 'Agency access required' using errcode='42501'; end if;
  select * into v_org from public.organizations where id=p_organization for update;
  if not found then raise exception 'Workspace not found' using errcode='22023'; end if;
  select * into v_event from public.events where id=p_event for update;
  if not found then raise exception 'Event not found' using errcode='22023'; end if;
  if v_event.organization_id=p_organization then return; end if;
  if v_event.organization_id is not null then raise exception 'This event already belongs to another workspace' using errcode='PT409'; end if;
  if v_org.event_limit is not null and (select count(*) from public.events where organization_id=p_organization)>=v_org.event_limit then raise exception 'Increase the workspace event limit before moving this event' using errcode='22023'; end if;
  update public.events set organization_id=p_organization,organization_slug=v_org.slug,platform_version=platform_version+1 where id=p_event;
  perform private.platform_log(p_organization,p_event,'event.adopted');
end $$;
create function private.platform_support_open(p_organization uuid) returns void language plpgsql security definer set search_path='' as $$
begin
  if not private.is_platform_owner() then raise exception 'Agency access required' using errcode='42501'; end if;
  if not exists(select 1 from public.organizations where id=p_organization) then raise exception 'Workspace not found' using errcode='22023'; end if;
  perform private.platform_log(p_organization,null,'support.workspace_opened');
end $$;

-- Only workspace owners may see the verified account identities of their
-- staff. This is separate from attendee contact data and public profiles.
create function private.platform_team_members(p_organization uuid)
returns table(organization_id uuid,user_id uuid,email text,role text,status text,version integer)
language plpgsql stable security definer set search_path='' as $$
begin
  if not private.owns_organization(p_organization) then raise exception 'Workspace owner access required' using errcode='42501'; end if;
  return query select m.organization_id,m.user_id,u.email::text,m.role,m.status,m.version
    from public.organization_memberships m join auth.users u on u.id=m.user_id
    where m.organization_id=p_organization order by m.created_at,m.user_id limit 200;
end $$;

-- Thin invoker wrappers. Privileged bodies remain unexposed and always verify
-- the caller; no service-role client is introduced into the application.
create function public.platform_access() returns boolean language sql stable security invoker set search_path='' as $$ select private.is_platform_owner(); $$;
create function public.platform_can_manage_organization(p_organization uuid) returns boolean language sql stable security invoker set search_path='' as $$ select private.can_manage_organization(p_organization); $$;
create function public.platform_owns_organization(p_organization uuid) returns boolean language sql stable security invoker set search_path='' as $$ select private.owns_organization(p_organization); $$;
create function public.platform_create_organization(p_request uuid,p_name text,p_slug text,p_owner_email text,p_event_limit integer default null) returns uuid language sql security invoker set search_path='' as $$ select private.platform_create_organization(p_request,p_name,p_slug,p_owner_email,p_event_limit); $$;
create function public.platform_accept_invitation(p_invitation uuid) returns uuid language sql security invoker set search_path='' as $$ select private.platform_accept_invitation(p_invitation); $$;
create function public.platform_invite_member(p_organization uuid,p_email text,p_role text) returns uuid language sql security invoker set search_path='' as $$ select private.platform_invite_member(p_organization,p_email,p_role); $$;
create function public.platform_revoke_invitation(p_organization uuid,p_invitation uuid) returns void language sql security invoker set search_path='' as $$ select private.platform_revoke_invitation(p_organization,p_invitation); $$;
create function public.platform_update_member(p_organization uuid,p_user uuid,p_role text,p_status text,p_version integer) returns void language sql security invoker set search_path='' as $$ select private.platform_update_member(p_organization,p_user,p_role,p_status,p_version); $$;
create function public.platform_update_organization(p_organization uuid,p_name text,p_version integer,p_status text default null,p_event_limit integer default null,p_set_limit boolean default false) returns void language sql security invoker set search_path='' as $$ select private.platform_update_organization(p_organization,p_name,p_version,p_status,p_event_limit,p_set_limit); $$;
create function public.platform_create_event(p_organization uuid,p_request uuid,p_values jsonb) returns uuid language sql security invoker set search_path='' as $$ select private.platform_create_event(p_organization,p_request,p_values); $$;
create function public.platform_update_event(p_organization uuid,p_event uuid,p_version integer,p_values jsonb) returns void language sql security invoker set search_path='' as $$ select private.platform_update_event(p_organization,p_event,p_version,p_values); $$;
create function public.platform_publish_event(p_organization uuid,p_event uuid,p_version integer,p_published boolean) returns void language sql security invoker set search_path='' as $$ select private.platform_publish_event(p_organization,p_event,p_version,p_published); $$;
create function public.platform_legacy_events() returns table(id uuid,slug text,name text,published boolean) language sql stable security invoker set search_path='' as $$ select * from private.platform_legacy_events(); $$;
create function public.platform_adopt_event(p_organization uuid,p_event uuid) returns void language sql security invoker set search_path='' as $$ select private.platform_adopt_event(p_organization,p_event); $$;
create function public.platform_support_open(p_organization uuid) returns void language sql security invoker set search_path='' as $$ select private.platform_support_open(p_organization); $$;

create function public.platform_team_members(p_organization uuid) returns table(organization_id uuid,user_id uuid,email text,role text,status text,version integer) language sql stable security invoker set search_path='' as $$ select * from private.platform_team_members(p_organization); $$;

-- Revoke both PostgreSQL PUBLIC defaults and Supabase's explicit role defaults.
do $$ declare fn record; begin
  for fn in select p.oid::regprocedure as signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where (n.nspname='private' and p.proname in ('platform_verified_email','is_platform_owner','can_manage_organization','owns_organization','can_see_organization','guard_platform_event_write','platform_log','platform_create_organization','platform_accept_invitation','platform_invite_member','platform_revoke_invitation','platform_update_member','platform_update_organization','platform_validate_event','platform_create_event','platform_update_event','platform_publish_event','platform_legacy_events','platform_adopt_event','platform_support_open','platform_team_members'))
    or (n.nspname='public' and p.proname in ('platform_access','platform_can_manage_organization','platform_owns_organization','platform_create_organization','platform_accept_invitation','platform_invite_member','platform_revoke_invitation','platform_update_member','platform_update_organization','platform_create_event','platform_update_event','platform_publish_event','platform_legacy_events','platform_adopt_event','platform_support_open','platform_team_members'))
  loop
    execute format('revoke all on function %s from public,anon,authenticated',fn.signature);
    if fn.proname not in ('guard_platform_event_write','platform_log','platform_validate_event') then execute format('grant execute on function %s to authenticated',fn.signature); end if;
  end loop;
end $$;
commit;
